int register_genl_family(struct genl_family *family) {
    int err = 0;

    if (!family) {
        return -EINVAL;
    }

    if (family->n_ops > GENL_MAX_OPS) {
        return -EINVAL;
    }

    for (int i = 0; i < family->n_ops; i++) {
        if (!family->ops[i].doit && !family->ops[i].dumpit) {
            return -EINVAL;
        }
    }

    if (family->n_attrs > GENL_MAX_ATTRS) {
        return -EINVAL;
    }

    if (family->maxattr && family->n_attrs == 0) {
        return -EINVAL;
    }

    if (family->name[GENL_NAMSZ - 1] != '\0') {
        return -EINVAL;
    }

    if (family->id != GENL_ID_GENERATE && family->id >= GENL_ID_MIN && family->id < GENL_ID_MAX) {
        return -EINVAL;
    }

    if (family->id == GENL_ID_GENERATE) {
        family->id = genl_get_unique_id();
    }

    if (family->id < 0) {
        return family->id;
    }

    for (int i = 0; i < family->n_multicast_groups; i++) {
        if (family->mcgrps[i].name[GENL_NAMSZ - 1] != '\0') {
            return -EINVAL;
        }

        if (family->mcgrps[i].id != GENL_ID_GENERATE && family->mcgrps[i].id >= GENL_ID_MIN && family->mcgrps[i].id < GENL_ID_MAX) {
            return -EINVAL;
        }

        if (family->mcgrps[i].id == GENL_ID_GENERATE) {
            family->mcgrps[i].id = genl_get_unique_id();
        }

        if (family->mcgrps[i].id < 0) {
            return family->mcgrps[i].id;
        }
    }

    return 0;
}
